CREATE TABLE users(id UUID PRIMARY KEY,email VARCHAR(320) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,role VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT ck_users_role CHECK(role IN ('CUSTOMER','ADMIN')),CONSTRAINT ck_users_status CHECK(status IN ('ACTIVE','DISABLED','PENDING')));CREATE INDEX idx_users_email ON users(email);